import"chrome://resources/polymer/v3_0/paper-spinner/paper-spinner-lite.js";import"./base_page.js";import"./shimless_rma_shared.css.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{I18nMixin}from"chrome://resources/ash/common/cr_elements/i18n_mixin.js";import{getTemplate}from"./reboot_page.html.js";import{RmadErrorCode}from"./shimless_rma.mojom-webui.js";import{focusPageTitle}from"./shimless_rma_util.js";const DELAY_DURATION="3";const RebootPageBase=I18nMixin(PolymerElement);export class RebootPage extends RebootPageBase{static get is(){return"reboot-page"}static get template(){return getTemplate()}static get properties(){return{errorCode:{type:Object}}}ready(){super.ready();focusPageTitle(this)}getPageTitle(){return this.errorCode===RmadErrorCode.kExpectReboot?this.i18n("rebootPageTitle"):this.i18n("shutdownPageTitle")}getPageInstructions(){return this.errorCode===RmadErrorCode.kExpectReboot?this.i18n("rebootPageMessage",DELAY_DURATION):this.i18n("shutdownPageMessage",DELAY_DURATION)}}customElements.define(RebootPage.is,RebootPage);